import { Accordion } from "@base-ui/react/accordion";
import { cn } from "cn";
import { ChevronDownIcon, ChevronUpIcon, PlusIcon } from "lucide-react";
import { MotionConfig, motion } from "motion/react";
import * as React from "react";

import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";

interface AccordionOSItem {
  /** 唯一标识；缺省用下标。 */
  id?: string | number;
  title: string;
  /** 展开时标题右侧的小标记，如序号。 */
  badge?: string;
  /** 展开后显示的说明。 */
  claim: React.ReactNode;
  /** 右侧大图的地址。 */
  image: string;
  /** 大图的替代文本；缺省用 title。 */
  alt?: string;
}

interface AccordionOSProps
  extends Omit<React.ComponentProps<"section">, "defaultValue" | "onChange" | "aria-label"> {
  /** 必填：区域名称，读屏软件用它称呼这个轮播（如「产品功能」）。 */
  label: string;
  items: AccordionOSItem[];
  /** 没有展开项时显示的图；缺省时显示 muted 底色。 */
  staticImage?: string;
  staticAlt?: string;
  /** 受控：当前展开项的下标，null 表示全部收起。 */
  value?: number | null;
  /** 非受控：初始展开项，默认 0。 */
  defaultValue?: number | null;
  onValueChange?: (index: number | null) => void;
  /** 自动轮播；用户开了「减少动态效果」时不轮播。默认 true。 */
  autoPlay?: boolean;
  /** 轮播间隔（毫秒），默认 3500。 */
  autoPlayInterval?: number;
  /** 指针悬停或焦点在组件内时暂停轮播，默认 true。 */
  pauseOnHover?: boolean;
}

/** 宽度 layout 动画的弹簧（上游原值）。弹簧没有对应的缓动令牌，留在这里。 */
const LAYOUT_SPRING = { type: "spring", stiffness: 340, damping: 28, mass: 0.8 } as const;

function useControllableIndex(
  value: number | null | undefined,
  defaultValue: number | null,
  onChange: ((index: number | null) => void) | undefined,
) {
  const [inner, setInner] = React.useState(defaultValue);
  const controlled = value !== undefined;
  const current = controlled ? value : inner;
  const set = React.useCallback(
    (next: number | null) => {
      if (!controlled) setInner(next);
      onChange?.(next);
    },
    [controlled, onChange],
  );
  return [current, set] as const;
}

function usePrefersReducedMotion() {
  const [reduced, setReduced] = React.useState(false);
  React.useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(query.matches);
    const onChange = () => setReduced(query.matches);
    query.addEventListener("change", onChange);
    return () => query.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

function AccordionOS({
  label,
  items,
  staticImage,
  staticAlt = "",
  value,
  defaultValue = 0,
  onValueChange,
  autoPlay = true,
  autoPlayInterval = 3500,
  pauseOnHover = true,
  className,
  ...props
}: AccordionOSProps) {
  const [active, setActive] = useControllableIndex(value, defaultValue, onValueChange);
  const [paused, setPaused] = React.useState(false);
  const reducedMotion = usePrefersReducedMotion();
  const count = items.length;

  const step = React.useCallback(
    (delta: 1 | -1) => {
      if (count === 0) return;
      setActive(active === null ? 0 : (active + delta + count) % count);
    },
    [active, count, setActive],
  );

  React.useEffect(() => {
    if (!autoPlay || reducedMotion || (pauseOnHover && paused) || count < 2) return;
    const timer = setInterval(() => step(1), autoPlayInterval);
    return () => clearInterval(timer);
  }, [autoPlay, autoPlayInterval, pauseOnHover, paused, reducedMotion, step, count]);

  const itemValue = (index: number) => String(items[index]?.id ?? index);

  return (
    <MotionConfig reducedMotion="user">
      <section
        data-slot="accordion-os"
        aria-label={label}
        aria-roledescription="轮播"
        className={cn("@container mx-auto h-130 w-full max-w-4xl select-none", className)}
        onPointerEnter={() => setPaused(true)}
        onPointerLeave={() => setPaused(false)}
        onFocus={() => setPaused(true)}
        onBlur={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget)) setPaused(false);
        }}
        {...props}
      >
        <div
          data-slot="accordion-os-card"
          className="relative flex size-full animate-in flex-row items-stretch justify-between overflow-hidden rounded-none bg-muted p-6 duration-500 ease-enter fade-in-0 zoom-in-95 slide-in-from-bottom-4 @max-2xl:flex-col @max-2xl:justify-start @max-2xl:p-3.5 @max-md:p-2.5"
        >
          <div
            data-slot="accordion-os-sidebar"
            className="relative z-10 flex h-full w-72 shrink-0 flex-col items-start justify-between @max-2xl:h-auto @max-2xl:w-full"
          >
            <Accordion.Root
              value={active === null ? [] : [itemValue(active)]}
              onValueChange={(next) => {
                const open = next.at(-1);
                setActive(
                  open === undefined ? null : items.findIndex((_, i) => itemValue(i) === open),
                );
              }}
              className="flex w-full flex-col items-start gap-2.5 @max-md:gap-2"
            >
              {items.map((item, index) => (
                <Accordion.Item
                  key={itemValue(index)}
                  value={itemValue(index)}
                  render={<motion.div layout transition={LAYOUT_SPRING} />}
                  className="w-fit max-w-72 border border-border bg-background/70 backdrop-blur-lg transition-colors duration-200 hover:bg-background/90 data-open:w-72 data-open:bg-background/90 @max-2xl:max-w-full @max-2xl:data-open:w-full"
                >
                  <Accordion.Header>
                    <Accordion.Trigger className="group/trigger flex w-full cursor-pointer items-center gap-3 px-4 py-3 text-left outline-none focus-visible:ring-1 focus-visible:ring-ring @max-2xl:px-3.5 @max-2xl:py-2.5">
                      <span
                        aria-hidden
                        className="flex size-5.5 shrink-0 items-center justify-center rounded-full border border-border bg-background text-foreground transition-all duration-200 ease-enter group-data-panel-open/trigger:rotate-135 group-data-panel-open/trigger:border-primary group-data-panel-open/trigger:bg-primary group-data-panel-open/trigger:text-primary-foreground"
                      >
                        <PlusIcon className="size-3.5" />
                      </span>
                      <span className="flex w-full items-center justify-between gap-2">
                        <span className="truncate text-sm font-medium text-foreground @max-2xl:whitespace-normal">
                          {item.title}
                        </span>
                        {item.badge ? (
                          <span className="hidden text-xs font-medium text-muted-foreground tabular-nums group-data-panel-open/trigger:inline">
                            {item.badge}
                          </span>
                        ) : null}
                      </span>
                    </Accordion.Trigger>
                  </Accordion.Header>
                  {/* 展开用 ease-enter，收起（data-closed）用 ease-exit；h-(--accordion-panel-height) 是 CSS 变量简写，不是任意值。 */}
                  <Accordion.Panel className="h-(--accordion-panel-height) overflow-hidden transition-all duration-300 ease-enter data-closed:ease-exit data-ending-style:h-0 data-ending-style:opacity-0 data-starting-style:h-0 data-starting-style:opacity-0">
                    <p className="px-4 pb-3 text-xs text-muted-foreground @max-2xl:px-3.5">
                      {item.claim}
                    </p>
                  </Accordion.Panel>
                </Accordion.Item>
              ))}
            </Accordion.Root>

            <div
              data-slot="accordion-os-nav"
              data-active={active !== null}
              className="z-10 mt-auto flex items-center gap-2 border border-border bg-background/70 p-1 backdrop-blur-md transition-all duration-200 ease-enter data-[active=false]:pointer-events-none data-[active=false]:translate-y-4 data-[active=false]:opacity-0 data-[active=false]:ease-exit @max-2xl:mt-4 @max-2xl:mb-3"
            >
              <Tooltip>
                <TooltipTrigger
                  render={
                    <Button
                      variant="ghost"
                      size="icon-xs"
                      aria-label="上一项"
                      onClick={() => step(-1)}
                    />
                  }
                >
                  <ChevronUpIcon />
                </TooltipTrigger>
                <TooltipContent>上一项</TooltipContent>
              </Tooltip>
              <span className="flex items-center gap-1 text-xs font-medium text-muted-foreground tabular-nums">
                <span>{String((active ?? 0) + 1).padStart(2, "0")}</span>
                <span className="opacity-40">/</span>
                <span>{String(count).padStart(2, "0")}</span>
              </span>
              <Tooltip>
                <TooltipTrigger
                  render={
                    <Button
                      variant="ghost"
                      size="icon-xs"
                      aria-label="下一项"
                      onClick={() => step(1)}
                    />
                  }
                >
                  <ChevronDownIcon />
                </TooltipTrigger>
                <TooltipContent>下一项</TooltipContent>
              </Tooltip>
            </div>
          </div>

          <div data-slot="accordion-os-visual" className="pointer-events-none absolute inset-0 z-0">
            {staticImage ? (
              <img
                src={staticImage}
                alt={staticAlt}
                data-active={active === null}
                className="absolute inset-0 size-full rounded-none object-cover transition-all duration-500 ease-enter data-[active=false]:scale-105 data-[active=false]:opacity-0 data-[active=false]:ease-exit"
              />
            ) : null}
            {items.map((item, index) => (
              <img
                key={itemValue(index)}
                src={item.image}
                alt={item.alt ?? item.title}
                data-active={active === index}
                className="absolute inset-0 size-full rounded-none object-cover transition-all duration-500 ease-enter data-[active=false]:scale-105 data-[active=false]:opacity-0 data-[active=false]:ease-exit"
              />
            ))}
          </div>
        </div>
      </section>
    </MotionConfig>
  );
}

export { AccordionOS, type AccordionOSItem, type AccordionOSProps };
